-- =====================================================================
-- 아낄맵 시연용 시드 데이터 (지라 S15P11A508-144 / B1)
-- 원본: dummy_data.csv sha256[:16]=716d33dfcec91c7d · 거래 1866건 · 2026년 1년치 · 페르소나 1명
-- 생성기: PoC-AI/ai-agent experiments/make_seed_sql.py (수정은 생성기에서, 이 파일 직접 편집 금지)
-- 전제: 백엔드 앱이 한 번 떠서 테이블이 생성된 상태(ddl-auto: update). PostGIS 확장 필요.
-- 사용: psql -h localhost -U <user> -d <db> -f seed.sql
-- ⚠ TRUNCATE 포함 — 기존 데이터를 지운다. 시연 DB 전용.
-- =====================================================================
BEGIN;

TRUNCATE transaction_history, my_place, category, users RESTART IDENTITY CASCADE;

-- users (provider 는 enum STRING: 'GOOGLE')

-- category (11종, DefaultCategory 순서. 이름 컬럼은 엔티티 기준 `name`)

-- my_place ('집' 이름은 배달 판별·집 의존 사실의 앵커 — 설계 문서 §3.1)

-- transaction_history 1866건 (branch=NULL: 실서비스 API가 채우지 않는 컬럼)

-- 시퀀스 보정 (명시적 id 삽입 뒤 필수)
SELECT setval(pg_get_serial_sequence('users', 'user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('category', 'category_id'), (SELECT MAX(category_id) FROM category));
SELECT setval(pg_get_serial_sequence('my_place', 'my_place_id'), (SELECT MAX(my_place_id) FROM my_place));
SELECT setval(pg_get_serial_sequence('transaction_history', 'transaction_id'), (SELECT MAX(transaction_id) FROM transaction_history));

COMMIT;

-- ===================== 체크섬 (적재 후 실행, 전부 OK 여야 함) =====================
SELECT * FROM (VALUES
  ('행수: users=1', CASE WHEN (SELECT COUNT(*) FROM users) = 1 THEN 'OK' ELSE 'FAIL' END),
  ('행수: category=11', CASE WHEN (SELECT COUNT(*) FROM category) = 11 THEN 'OK' ELSE 'FAIL' END),
  ('행수: my_place=2', CASE WHEN (SELECT COUNT(*) FROM my_place) = 2 THEN 'OK' ELSE 'FAIL' END),
  ('행수: 거래=1866', CASE WHEN (SELECT COUNT(*) FROM transaction_history) = 1866 THEN 'OK' ELSE 'FAIL' END),
  ('수입 합계=25150500', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE type='INCOME') = 25150500 THEN 'OK' ELSE 'FAIL' END),
  ('지출 합계=25136100', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE type='EXPENSE') = 25136100 THEN 'OK' ELSE 'FAIL' END),
  ('재량비=16490200 (obs07 대조)', CASE WHEN (SELECT COALESCE(SUM(amount),0) FROM transaction_history WHERE type='EXPENSE' AND payment_method NOT IN ('자동이체','계좌이체')) = 16490200 THEN 'OK' ELSE 'FAIL' END),
  ('branch 전부 NULL', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE branch IS NOT NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('b_code 결측 0', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE b_code IS NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('좌표 결측 0', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE coordinate IS NULL) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('기간 시작=2026-01-01', CASE WHEN (SELECT MIN(datetime AT TIME ZONE 'Asia/Seoul')::date FROM transaction_history) = DATE '2026-01-01' THEN 'OK' ELSE 'FAIL' END),
  ('기간 끝=2026-12-31', CASE WHEN (SELECT MAX(datetime AT TIME ZONE 'Asia/Seoul')::date FROM transaction_history) = DATE '2026-12-31' THEN 'OK' ELSE 'FAIL' END),
  ('''집'' 장소 존재', CASE WHEN (SELECT COUNT(*) FROM my_place WHERE place_name = '집') = 1 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 1(음식점)=449건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 1) = 449 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 2(카페·간식)=496건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 2) = 496 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 3(편의점·마트)=242건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 3) = 242 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 4(쇼핑)=28건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 4) = 28 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 5(여가)=35건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 5) = 35 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 6(교통)=500건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 6) = 500 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 7(건강·의료)=4건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 7) = 4 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 8(생활)=84건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 8) = 84 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 9(미용)=8건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 9) = 8 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 10(교육)=0건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 10) = 0 THEN 'OK' ELSE 'FAIL' END),
  ('카테고리 11(기타)=20건', CASE WHEN (SELECT COUNT(*) FROM transaction_history WHERE category_id = 11) = 20 THEN 'OK' ELSE 'FAIL' END)
) AS checks(item, result);
